"""CPU geometry and observations for one-way to one-way left turns.

Curb gaps are measured physical quantities, not a legal definition of
'as close as practicable'. The two one-way directions are north and west.
"""
from dataclasses import dataclass
from math import cos, sin, pi, isfinite, hypot

@dataclass(frozen=True)
class Case:
    name: str
    approach_center_x: float
    departure_center_y: float

CASES={
 'left_edge_reference':Case('left_edge_reference',-4.5,-4.5),
 'approach_shifted_right':Case('approach_shifted_right',-3.5,-4.5),
 'departure_shifted_right':Case('departure_shifted_right',-4.5,-3.5),
}

CURB=-6.0
BODY_HALF_WIDTH=.9


def route(case, samples=12):
    """Continuous quarter arc with tangent northbound entry and westbound exit."""
    if samples<3: raise ValueError('arc sampling too sparse')
    # The centre of curvature lies to the left of the incoming heading.
    radius=4.5
    cx=case.approach_center_x-radius
    cy=case.departure_center_y-radius
    arc=[(cx+radius*cos(i*pi/(2*samples)),cy+radius*sin(i*pi/(2*samples)))
         for i in range(samples+1)]
    points=[(case.approach_center_x,-60.0),(case.approach_center_x,cy)]
    points.extend(arc[1:])
    points.append((-60.0,case.departure_center_y))
    return points


def construct(adapter,case):
    roads=adapter.one_way_intersection(approach_direction='north',
                                       departure_direction='west',
                                       approach_left_curb_x=CURB,
                                       departure_left_curb_y=CURB,
                                       roadway_half_width_m=6.0)
    path=route(case)
    ego=adapter.vehicle(role='ego',route=path,maneuver='left_turn',target_mps=5.0)
    return {'roads':roads,'ego':ego,'route':path}


def measure(samples):
    """Measure full-body left edge against the corresponding physical curb."""
    if len(samples)<2: raise ValueError('missing approach/departure history')
    observed=[]; last=None
    for s in samples:
        if not s.get('body_corners_xy') or len(s['body_corners_xy'])<4:
            raise ValueError('missing measured body footprint')
        if any(len(p)!=2 or not all(isinstance(v,(int,float)) and isfinite(v) for v in p)
               for p in s['body_corners_xy']):
            raise ValueError('invalid measured body footprint')
        if s.get('native_road_direction') not in ('north','turn','west'):
            raise ValueError('one-way direction unverified')
        if not isinstance(s.get('time_s'),(int,float)) or not isfinite(s['time_s']) or (last is not None and s['time_s']<=last):
            raise ValueError('nonmonotonic time')
        last=s['time_s']
        if s['native_road_direction']=='north':
            if not isinstance(s.get('observed_left_curb_x'),(int,float)) or not isfinite(s['observed_left_curb_x']):
                raise ValueError('missing original approach curb')
            gap=min(p[0] for p in s['body_corners_xy'])-s['observed_left_curb_x']
            segment='approach'
        elif s['native_road_direction']=='west':
            if not isinstance(s.get('observed_left_curb_y'),(int,float)) or not isfinite(s['observed_left_curb_y']):
                raise ValueError('missing original departure curb')
            gap=min(p[1] for p in s['body_corners_xy'])-s['observed_left_curb_y']
            segment='departure'
        else:
            polyline=s.get('turn_left_edge_polyline_xy')
            if (not isinstance(polyline,list) or len(polyline)<2 or
                    any(not isinstance(p,list) or len(p)!=2 or
                        any(type(v) not in (int,float) or not isfinite(v) for v in p)
                        for p in polyline)):
                raise ValueError('missing surveyed turn curb polyline')
            def signed_gap(point):
                choices=[]
                for a,b in zip(polyline,polyline[1:]):
                    dx,dy=b[0]-a[0],b[1]-a[1]
                    length2=dx*dx+dy*dy
                    if length2<=1e-12:raise ValueError('degenerate turn curb polyline')
                    t=max(0.,min(1.,((point[0]-a[0])*dx+(point[1]-a[1])*dy)/length2))
                    px,py=a[0]+t*dx,a[1]+t*dy
                    distance=hypot(point[0]-px,point[1]-py)
                    cross=dx*(point[1]-py)-dy*(point[0]-px)
                    choices.append((distance,distance if cross<=0 else -distance))
                return min(choices)[1]
            gap=min(signed_gap(p) for p in s['body_corners_xy'])
            segment='turn'
        observed.append({'time_s':s['time_s'],'segment':segment,'left_body_to_curb_gap_m':gap,
                         'source':s['source']})
    if {'approach','turn','departure'}!={r['segment'] for r in observed}:
        raise ValueError('approach, turn and departure all required')
    return {'samples':observed,
            'minimum_approach_gap_m':min(r['left_body_to_curb_gap_m'] for r in observed if r['segment']=='approach'),
            'minimum_departure_gap_m':min(r['left_body_to_curb_gap_m'] for r in observed if r['segment']=='departure'),
            'minimum_turn_gap_m':min((r['left_body_to_curb_gap_m'] for r in observed if r['segment']=='turn'),default=None),
            'legal_practicability_judgment':'unresolved'}


def audit_comparison(a,b,declared):
    if not a.get('samples') or not b.get('samples'):
        raise ValueError('missing measured body history')
    for key in ('map_hash','curb_geometry_hash','road_directions','controller_policy_hash',
                'camera_plan_hash','duration_s'):
        if a.get(key) is None or a.get(key)!=b.get(key):
            raise ValueError('fixed condition differs: '+key)
    changed={key for key in ('approach_center_x','departure_center_y') if a.get(key)!=b.get(key)}
    if changed!=set(declared): raise ValueError('undeclared approach/departure difference')
    return {'fixed_conditions_checked':True,'legal_practicability_judgment':'unresolved'}

"""CARLA-lazy survey of a source-bound one-way to one-way left-turn site.

The site file is a proposed map inventory. The runtime readback checks identity,
lane connectivity and actual direction; a declared sign alone proves nothing.
"""
import hashlib
import json
from math import atan2, degrees, radians, sin, cos
from pathlib import Path


def _heading_delta(a, b):
    d = radians(float(b.transform.rotation.yaw) - float(a.transform.rotation.yaw))
    return degrees(atan2(sin(d), cos(d)))


def _identity(wp):
    return (int(wp.road_id), int(wp.lane_id))


def _read_waypoint(world_map, selector):
    road = int(selector['road_id'])
    lane = int(selector['lane_id'])
    s = float(selector['s_m'])
    wp = world_map.get_waypoint_xodr(road, lane, s)
    if wp is None or _identity(wp) != (road, lane):
        raise ValueError('surveyed OpenDRIVE lane not present in Native map')
    if str(wp.lane_type).split('.')[-1].lower() != 'driving':
        raise ValueError('surveyed lane is not a Native driving lane')
    return wp


def _no_opposing_driving_lane(wp):
    """Reject a driving lane with the opposite OpenDRIVE lane sign on this road."""
    seen = set()
    queue = [wp]
    while queue:
        current = queue.pop()
        if current is None or id(current) in seen:
            continue
        seen.add(id(current))
        if int(current.road_id) == int(wp.road_id) and str(current.lane_type).split('.')[-1].lower() == 'driving':
            if int(current.lane_id) * int(wp.lane_id) < 0:
                raise ValueError('opposing driving lane on proposed one-way road')
        if len(seen) > 24:
            raise ValueError('lane cross-section survey exceeded bound')
        queue.extend([current.get_left_lane(), current.get_right_lane()])


def survey(world_map, site_path):
    path = Path(site_path)
    site = json.loads(path.read_text())
    od = world_map.to_opendrive()
    digest = hashlib.sha256(od.encode()).hexdigest()
    if digest != site.get('opendrive_sha256'):
        raise ValueError('Native OpenDRIVE hash differs from site survey')
    if not site.get('source_id') or not site.get('direction_sign_source'):
        raise ValueError('site or direction sign source absent')
    approach = _read_waypoint(world_map, site['approach'])
    departure = _read_waypoint(world_map, site['departure'])
    if _identity(approach)[0] == _identity(departure)[0]:
        raise ValueError('two intersecting one-way roads required')
    _no_opposing_driving_lane(approach)
    _no_opposing_driving_lane(departure)
    delta = _heading_delta(approach, departure)
    if not 55 <= delta <= 125:
        raise ValueError('Native departure is not a left turn')
    # The map graph must connect the actual approach to the selected exit.
    frontier = [(approach, 0, [approach])]
    visited = set()
    connected_route = None
    while frontier:
        wp, depth, route = frontier.pop(0)
        key = (int(wp.road_id), int(wp.lane_id), round(float(wp.s), 1))
        if key in visited:
            continue
        visited.add(key)
        if _identity(wp) == _identity(departure) and abs(float(wp.s)-float(departure.s)) <= 8:
            connected_route = route
            break
        if depth < 80:
            frontier.extend((nxt, depth+1, route+[nxt]) for nxt in wp.next(2.0))
    if connected_route is None:
        raise ValueError('approach does not connect to selected left-turn exit')
    return {'approach': approach, 'departure': departure,
            'opendrive_sha256': digest, 'site_source_id': site['source_id'],
            'direction_sign_source': site['direction_sign_source'],
            'left_turn_heading_delta_deg': delta,
            'connected_route': connected_route}

"""Four synchronized original RGB source streams for turn probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown turn source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior turn camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original turn camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Turn source encoder failed")


class TurnCameraCapture:
    def __init__(self, world, carla_module, ego, sinks, *, overview_height_delta_m=0):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named turn source sinks required")
        if overview_height_delta_m not in (0, 2):
            raise ValueError("Unsupported overview camera height change")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                if name == 'overview':
                    loc = (loc[0], loc[1], loc[2] + overview_height_delta_m)
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original turn camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original turn camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Turn source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original turn source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original turn camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Saved-only original-source measurements for the one-way left-turn cases.

This module consumes retained Native rows. It does not infer a legal cutoff for
"as close as practicable" or take the requested construction as observed fact.
"""
import argparse
import hashlib
import json
from pathlib import Path

from one_way_left import measure


REQUIRED = ('video_frames.jsonl', 'native/footprints.jsonl', 'native/road_edges.jsonl', 'site.json')


def _rows(path):
    if not path.is_file():
        raise ValueError('missing original source: ' + str(path))
    data = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    if not data:
        raise ValueError('empty original source: ' + str(path))
    return data


def _key(row):
    try:
        if type(row['video_frame']) is not int or type(row['native_frame']) is not int:
            raise ValueError('original frame identity type invalid')
        if row.get('carla_frame') != row['native_frame']:
            raise ValueError('CARLA/native original identity differs')
        return (row['video_frame'], row['native_frame'])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('original frame identity missing') from exc


def _index(rows, label):
    out = {}
    for row in rows:
        key = _key(row)
        if key in out:
            raise ValueError('duplicate ' + label + ' frame')
        out[key] = row
    return out


def finalize(source_dir):
    root = Path(source_dir)
    sources = {name: root / name for name in REQUIRED}
    site = json.loads(sources['site.json'].read_text()) if sources['site.json'].is_file() else None
    if not isinstance(site, dict) or not site.get('curb_source') or not site.get('one_way_source'):
        raise ValueError('missing original source: site.json')
    site_sha = hashlib.sha256(sources['site.json'].read_bytes()).hexdigest()
    frame_rows = _rows(sources['video_frames.jsonl'])
    bodies = _index(_rows(sources['native/footprints.jsonl']), 'footprint')
    edges = _index(_rows(sources['native/road_edges.jsonl']), 'road edge')
    frames = _index(frame_rows, 'frame map')
    if set(frames) != set(bodies) or set(frames) != set(edges):
        raise ValueError('original frame/source join incomplete')
    if [key[0] for key in sorted(frames)] != list(range(len(frames))):
        raise ValueError('original video frame sequence incomplete')
    observed = []
    prior_time = None
    for key in sorted(frames):
        frame, body, edge = frames[key], bodies[key], edges[key]
        t = frame.get('time_s')
        if not isinstance(t, (int, float)) or (prior_time is not None and t <= prior_time):
            raise ValueError('nonmonotonic original time')
        prior_time = t
        if body.get('actor_id') != frame.get('subject_actor_id'):
            raise ValueError('subject actor identity differs')
        if body.get('road_id') != edge.get('road_id'):
            raise ValueError('original road identity differs')
        if not edge.get('one_way_source') or not edge.get('curb_source'):
            raise ValueError('original one-way or curb source absent')
        if (edge.get('site_file_sha256') != site_sha or
                edge.get('turn_left_edge_polyline_xy') != site.get('turn_left_edge_polyline_xy') or
                edge.get('curb_source') != site['curb_source'] or
                edge.get('one_way_source') != site['one_way_source']):
            raise ValueError('original curb/site source binding differs')
        if edge.get('native_road_direction') not in ('north', 'turn', 'west'):
            raise ValueError('unverified one-way direction')
        observed.append({
            'time_s': t,
            'native_road_direction': edge['native_road_direction'],
            'body_corners_xy': body.get('body_corners_xy'),
            'observed_left_curb_x': edge.get('observed_left_curb_x'),
            'observed_left_curb_y': edge.get('observed_left_curb_y'),
            'turn_left_edge_polyline_xy': edge.get('turn_left_edge_polyline_xy'),
            'source': 'native/footprints.jsonl + native/road_edges.jsonl',
        })
    result = measure(observed)
    result['original_frame_count'] = len(frames)
    result['source_sha256'] = {name: hashlib.sha256(path.read_bytes()).hexdigest()
                               for name, path in sources.items()}
    result['source_kind'] = 'retained_original_native'
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--source-dir', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    result = finalize(args.source_dir)
    Path(args.output).write_text(json.dumps(result, indent=2, sort_keys=True) + '\n')


if __name__ == '__main__':
    main()

"""Independent original-source audit for C152976, without legal acceptance."""
import argparse
from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')
SOURCES = ('site.json', 'video_frames.jsonl', 'native/footprints.jsonl',
           'native/road_edges.jsonl', 'trace.jsonl')


def _hash(path):
    return sha256(Path(path).read_bytes()).hexdigest()


def _rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def _signed_turn_gap(point, polyline):
    near = []
    for a, b in zip(polyline, polyline[1:]):
        dx, dy = b[0]-a[0], b[1]-a[1]
        length = dx*dx+dy*dy
        if length <= 1e-12: raise ValueError('Degenerate audited turn curb')
        t = max(0., min(1., ((point[0]-a[0])*dx+(point[1]-a[1])*dy)/length))
        x, y = a[0]+t*dx, a[1]+t*dy
        dist = hypot(point[0]-x, point[1]-y)
        cross = dx*(point[1]-y)-dy*(point[0]-x)
        near.append((dist, dist if cross<=0 else -dist))
    return min(near)[1]


def audit_attempt(attempt, analysis, case, *, decoder=None, receipt_dir=None):
    root = Path(attempt)
    report = json.loads(Path(analysis).read_text()) if not isinstance(analysis, dict) else analysis
    if report.get('case_id') != case:
        raise ValueError('Audited analysis selects another case')
    for name in (*SOURCES, 'config.json'):
        if not (root/name).is_file():
            raise ValueError('Missing audited original source: '+name)
    config = json.loads((root/'config.json').read_text())
    if config.get('selected_case_id') != case:
        raise ValueError('Audited Native config selects another case')
    source_hashes = report['measurements']['one_way_curb_history'].get('sources', {})
    expected = {'site.json','video_frames.jsonl','native/footprints.jsonl','native/road_edges.jsonl'}
    if set(source_hashes) != expected or any(_hash(root/name) != source_hashes[name] for name in expected):
        raise ValueError('Audited analysis source inventory differs')
    site = json.loads((root/'site.json').read_text())
    if not site.get('curb_source') or not site.get('one_way_source'):
        raise ValueError('Audited site lacks source identity')
    frames = _rows(root/'video_frames.jsonl')
    bodies = _rows(root/'native/footprints.jsonl')
    edges = _rows(root/'native/road_edges.jsonl')
    trace = _rows(root/'trace.jsonl')
    if not frames or len({len(frames),len(bodies),len(edges),len(trace)}) != 1:
        raise ValueError('Audited original source frame count differs')
    samples = report['measurements']['one_way_curb_history']['value']['samples']
    if len(samples) != len(frames):
        raise ValueError('Audited measured curb history incomplete')
    sections = set(); actor_id = None; minimum = {}
    for i,(frame,body,edge,motion,sample) in enumerate(zip(frames,bodies,edges,trace,samples)):
        ident = (frame.get('video_frame'),frame.get('carla_frame'),frame.get('time_s'))
        if ident[0] != i or frame.get('native_frame') != ident[1]:
            raise ValueError('Audited original frame map changed')
        if any((row.get('video_frame'),row.get('carla_frame'),row.get('time_s')) != ident
               for row in (body,edge)) or (motion.get('frame'),motion.get('time_s')) != ident[1:]:
            raise ValueError('Audited original time join differs')
        if actor_id is None: actor_id = body.get('actor_id')
        if actor_id != body.get('actor_id') or actor_id != frame.get('subject_actor_id'):
            raise ValueError('Audited subject actor identity changed')
        if edge.get('road_id') != body.get('road_id'):
            raise ValueError('Audited body/curb road identity differs')
        if (edge.get('site_file_sha256') != _hash(root/'site.json') or
                edge.get('one_way_source') != site['one_way_source'] or
                edge.get('curb_source') != site['curb_source'] or
                edge.get('turn_left_edge_polyline_xy') != site.get('turn_left_edge_polyline_xy')):
            raise ValueError('Audited site/curb binding differs')
        corners = body.get('body_corners_xy')
        if not isinstance(corners,list) or len(corners)<4 or any(
                not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) or not isfinite(v) for v in p)
                for p in corners):
            raise ValueError('Audited full-body corners missing')
        segment = edge.get('native_road_direction')
        if segment == 'north':
            gap = min(p[0] for p in corners)-edge['observed_left_curb_x']; label='approach'
        elif segment == 'west':
            gap = min(p[1] for p in corners)-edge['observed_left_curb_y']; label='departure'
        elif segment == 'turn':
            gap = min(_signed_turn_gap(p,site['turn_left_edge_polyline_xy']) for p in corners);label='turn'
        else: raise ValueError('Audited one-way route segment missing')
        if sample.get('segment') != label or abs(sample.get('left_body_to_curb_gap_m',float('inf'))-gap)>1e-6:
            raise ValueError('Audited curb measurement differs from original bodies')
        sections.add(label);minimum[label]=min(gap,minimum.get(label,gap))
    if sections != {'approach','turn','departure'}:
        raise ValueError('Audited approach/turn/departure coverage incomplete')
    value = report['measurements']['one_way_curb_history']['value']
    for label,key in [('approach','minimum_approach_gap_m'),('turn','minimum_turn_gap_m'),('departure','minimum_departure_gap_m')]:
        if abs(minimum[label]-value[key])>1e-6:
            raise ValueError('Audited segment minimum differs')
    if decoder is None:
        from worker_exchange.media import audit as decoder
    if receipt_dir is not None: Path(receipt_dir).mkdir(parents=True,exist_ok=False)
    cameras={}
    for name in CAMERAS:
        path=root/(name+'.mkv')
        if not path.is_file():raise ValueError('Missing audited original camera: '+name)
        receipt=None if receipt_dir is None else Path(receipt_dir)/(name+'-decode.json')
        decoded=decoder(path,len(frames),mapping_sha256=_hash(root/'video_frames.jsonl'),receipt=receipt)
        if decoded.get('frames')!=len(frames):raise ValueError('Audited full camera decode incomplete')
        cameras[name]={'source_sha256':_hash(path),'decode':decoded}
    return {'format':'worker-one-way-source-audit','case_id':case,'frame_count':len(frames),
            'source_hashes':source_hashes,'camera_decodes':cameras,
            'segment_minima_m':minimum,
            'checks':{'native_source':True,'all_participants':True,'time_join':True,
                      'full_video_decode':True,'actual_pixels':'source_frames_decoded_only',
